<?php
session_start();
require 'baseDeDatos.php';
requireAuthentication();
$estadisticas = $conn->query('SELECT j.ci, CONCAT(j.nombre, " ", j.apellido) AS jugador, c.nombre AS club, COALESCE(SUM(e.goles),0) AS goles, COALESCE(SUM(e.asistencias),0) AS asistencias, COALESCE(SUM(e.amarillas),0) AS amarillas, COALESCE(SUM(e.rojas),0) AS rojas, COUNT(DISTINCT e.id_partido) AS partidos FROM jugadores j JOIN club c ON c.id_club=j.id_club LEFT JOIN estadisticas e ON e.ci_jugador=j.ci GROUP BY j.ci,j.nombre,j.apellido,c.nombre ORDER BY goles DESC, jugador');
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Estadísticas</title><link href="CSSmenuInicio.css" rel="stylesheet"><style>main{padding:20px}table{border-collapse:collapse;width:100%;margin-top:25px;background:#fff}th,td{padding:9px;border:1px solid #ddd}th{background:#2c3e50;color:#fff}</style></head><body><header><div class="MGfut"><h2>MG Fut</h2></div></header><main><p><a href="menuInicio.php">Volver al menú</a></p><h2>Estadísticas calculadas</h2><p>Los valores se obtienen de las actuaciones registradas en cada partido.</p><table><tr><th>Jugador</th><th>Club</th><th>Partidos</th><th>Goles</th><th>Asistencias</th><th>Amarillas</th><th>Rojas</th></tr><?php while($e=$estadisticas->fetch_assoc()): ?><tr><td><?php echo htmlspecialchars($e['jugador']); ?></td><td><?php echo htmlspecialchars($e['club']); ?></td><td><?php echo $e['partidos']; ?></td><td><?php echo $e['goles']; ?></td><td><?php echo $e['asistencias']; ?></td><td><?php echo $e['amarillas']; ?></td><td><?php echo $e['rojas']; ?></td></tr><?php endwhile; ?></table></main></body></html>
